{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "13-cis-retinoic acid, a close retinoid analogue, has low absolute oral bioavailability with significant gut degradation, supporting F<20% for the similarly lipophilic retinoid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Tretinoin, another retinoid, is reported to have approximately 50% oral bioavailability, suggesting some retinoids can exceed 20%, but this is not an absolute measurement and the compound differs from the query retinamide structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lutein, a highly lipophilic carotenoid, reached 55% bioavailability when formulated as liquefied spinach, indicating that lipophilic molecules can be well absorbed with appropriate formulation or food, but this is not an absolute measurement and is not a retinoid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Paracetamol, which shares the 4-hydroxyanilide substructure, has high absolute oral bioavailability (~82%), but its much lower lipophilicity and smaller size limit transferability to the query's absorption liabilities.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low (F<20%). The strongest endpoint-matched evidence is a close retinoid analogue with low absolute bioavailability; other high values come from less direct or non-absolute measurements and are outweighed by the retinoid-specific absorption liability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No human IV comparator data for the query.",
    "Formulation and food effects on absorption are not directly evidenced for the query.",
    "Conflicting retinoid bioavailability estimates create uncertainty in cross-molecule transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

